mapper.select:
SELECT mr.match_date, c.category_name, mr.team_result, t.team_code
FROM match_record mr
    JOIN category c ON mr.category_id = c.id
    JOIN team t ON mr.supporting_team_id = t.id
WHERE mr.user_id = #{userId, jdbcType = BINARY, typeHandler=com.example.backend.global.mybatis.UUIDTypeHandler}

    AND mr.category_id = #{categoryId, jdbcType = BINARY, typeHandler=com.example.backend.global.mybatis.UUIDTypeHandler}
